-- ============================================================
--  patch_eons_full.sql — Eons CMS
--  Patch complet : schéma + données
--  Base cible : eons_auth
--
--  Ordre d'exécution :
--    1. Colonnes dp / vp sur account
--    2. Tables boutique DP (log + queue)
--    3. Tables boutique VP (log + queue)
--    4. Tables votes VP
--    5. Table news
--    6. Table zones (+ 6 732 entrées WoW 3.3.5a)
--    7. Table dp_donations
--
--  Idempotent : utilise ADD COLUMN IF NOT EXISTS,
--  CREATE TABLE IF NOT EXISTS et INSERT IGNORE.
--  Peut être rejoué sans risque.
-- ============================================================

USE `auth_test`;

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';

-- ============================================================
--  §1. Colonnes account : dp + vp
-- ============================================================

  ALTER TABLE `account`
    ADD COLUMN `dp` INT UNSIGNED NOT NULL DEFAULT 0;
	
	  ALTER TABLE `account`
    ADD COLUMN `vp` INT UNSIGNED NOT NULL DEFAULT 0;
  
-- ============================================================
--  §2. Boutique DP — Log + Queue
-- ============================================================
  
-- ----------------------------
-- Table structure for dp_donations
-- ----------------------------
DROP TABLE IF EXISTS `dp_donations`;
CREATE TABLE `dp_donations`  (
  `id` int(0) UNSIGNED NOT NULL AUTO_INCREMENT,
  `account_id` int(0) UNSIGNED NOT NULL,
  `stripe_session` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `tier_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `amount_eur` smallint(0) UNSIGNED NOT NULL,
  `dp_granted` int(0) UNSIGNED NOT NULL,
  `status` enum('pending','completed','failed') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'pending',
  `created_at` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0),
  `completed_at` datetime(0) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_session`(`stripe_session`) USING BTREE,
  INDEX `idx_account`(`account_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

-- ============================================================
--  §2. Boutique DP — Log + Queue
-- ============================================================

CREATE TABLE IF NOT EXISTS `dp_shop_log` (
  `id`           INT UNSIGNED     NOT NULL AUTO_INCREMENT,
  `account_id`   INT UNSIGNED     NOT NULL,
  `char_name`    VARCHAR(64)      NOT NULL DEFAULT '',
  `item_id`      VARCHAR(64)      NOT NULL,
  `item_name`    VARCHAR(128)     NOT NULL,
  `game_item_id` INT UNSIGNED     NOT NULL DEFAULT 0,
  `cost`         INT UNSIGNED     NOT NULL,
  `currency`     ENUM('dp','vp')  NOT NULL DEFAULT 'dp',
  `soap_status`  ENUM('ok','failed','service','na') NOT NULL DEFAULT 'ok',
  `soap_error`   TEXT             NULL,
  `created_at`   DATETIME         NOT NULL DEFAULT NOW(),
  PRIMARY KEY (`id`),
  KEY `idx_account` (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='Historique achats boutique DP';

CREATE TABLE IF NOT EXISTS `dp_shop_queue` (
  `id`           INT UNSIGNED      NOT NULL AUTO_INCREMENT,
  `account_id`   INT UNSIGNED      NOT NULL,
  `char_name`    VARCHAR(64)       NOT NULL,
  `item_id`      VARCHAR(64)       NOT NULL,
  `item_name`    VARCHAR(128)      NOT NULL,
  `game_item_id` INT UNSIGNED      NOT NULL,
  `quantity`     SMALLINT UNSIGNED NOT NULL DEFAULT 1,
  `currency`     ENUM('dp','vp')   NOT NULL DEFAULT 'dp',
  `status`       ENUM('pending','delivered','error') NOT NULL DEFAULT 'pending',
  `attempts`     TINYINT UNSIGNED  NOT NULL DEFAULT 0,
  `created_at`   DATETIME          NOT NULL DEFAULT NOW(),
  `delivered_at` DATETIME          NULL,
  PRIMARY KEY (`id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='File de livraison boutique DP';

-- ============================================================
--  §3. Boutique VP — Log + Queue
-- ============================================================

CREATE TABLE IF NOT EXISTS `vp_shop_log` (
  `id`           INT UNSIGNED     NOT NULL AUTO_INCREMENT,
  `account_id`   INT UNSIGNED     NOT NULL,
  `char_name`    VARCHAR(64)      NOT NULL DEFAULT '',
  `item_id`      VARCHAR(64)      NOT NULL,
  `item_name`    VARCHAR(128)     NOT NULL,
  `game_item_id` INT UNSIGNED     NOT NULL DEFAULT 0,
  `cost`         INT UNSIGNED     NOT NULL,
  `soap_status`  ENUM('ok','failed','service','na') NOT NULL DEFAULT 'ok',
  `soap_error`   TEXT             NULL,
  `created_at`   DATETIME         NOT NULL DEFAULT NOW(),
  PRIMARY KEY (`id`),
  KEY `idx_account` (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='Historique achats boutique VP';

CREATE TABLE IF NOT EXISTS `vp_shop_queue` (
  `id`           INT UNSIGNED      NOT NULL AUTO_INCREMENT,
  `account_id`   INT UNSIGNED      NOT NULL,
  `char_name`    VARCHAR(64)       NOT NULL,
  `item_id`      VARCHAR(64)       NOT NULL,
  `item_name`    VARCHAR(128)      NOT NULL,
  `game_item_id` INT UNSIGNED      NOT NULL,
  `quantity`     SMALLINT UNSIGNED NOT NULL DEFAULT 1,
  `status`       ENUM('pending','delivered','error') NOT NULL DEFAULT 'pending',
  `attempts`     TINYINT UNSIGNED  NOT NULL DEFAULT 0,
  `created_at`   DATETIME          NOT NULL DEFAULT NOW(),
  `delivered_at` DATETIME          NULL,
  PRIMARY KEY (`id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='File de livraison boutique VP';

-- ============================================================
--  §4. Votes VP — Log + Pending
-- ============================================================

CREATE TABLE IF NOT EXISTS `vp_vote_log` (
  `id`         INT UNSIGNED     NOT NULL AUTO_INCREMENT,
  `account_id` INT UNSIGNED     NOT NULL,
  `site_id`    TINYINT UNSIGNED NOT NULL,
  `vp_reward`  SMALLINT UNSIGNED NOT NULL,
  `voted_at`   DATETIME         NOT NULL DEFAULT NOW(),
  PRIMARY KEY (`id`),
  KEY `idx_acc_site` (`account_id`, `site_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='Historique votes pour VP';

CREATE TABLE IF NOT EXISTS `vp_vote_pending` (
  `account_id` INT UNSIGNED     NOT NULL,
  `site_id`    TINYINT UNSIGNED NOT NULL,
  `clicked_at` DATETIME         NOT NULL DEFAULT NOW(),
  PRIMARY KEY (`account_id`, `site_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='Votes en attente de confirmation';

-- ============================================================
--  §5. News
-- ============================================================

CREATE TABLE IF NOT EXISTS `news` (
  `id`         INT(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `title`      VARCHAR(255)     NOT NULL,
  `slug`       VARCHAR(255)     NOT NULL DEFAULT '',
  `category`   ENUM('patch','event','maintenance','annonce','hotfix') NOT NULL DEFAULT 'annonce',
  `excerpt`    TEXT             NOT NULL,
  `content`    LONGTEXT         NOT NULL,
  `image_url`  VARCHAR(512)     NOT NULL DEFAULT '',
  `author`     VARCHAR(64)      NOT NULL DEFAULT 'Équipe Eons',
  `pinned`     TINYINT(1) UNSIGNED NOT NULL DEFAULT 0,
  `published`  TINYINT(1) UNSIGNED NOT NULL DEFAULT 1,
  `created_at` TIMESTAMP        NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP        NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_slug` (`slug`),
  KEY `idx_published_pinned` (`published`, `pinned`, `created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='Actualités du serveur';

